<?php $count=max(1,(int)ceil($total/$perPage));if($count>1):?><nav class="brochure-pagination" aria-label="Pagination"><?php if($number>1):?><a href="?<?=e(http_build_query(array_replace(request()->query(),['page'=>$number-1])))?>"><?=text('previous')?></a><?php endif?><span><?=text('page')?> <?=$number?> <?=text('of')?> <?=$count?></span><?php if($number<$count):?><a href="?<?=e(http_build_query(array_replace(request()->query(),['page'=>$number+1])))?>"><?=text('next')?></a><?php endif?></nav><?php endif?>
